<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Bootstrap\CanonicalJson;use App\Imperium\Runtime\Foundry\SubordinateConstructionAuthorizationAcceptanceService;use PHPUnit\Framework\TestCase;
final class SubordinateConstructionAuthorizationAcceptanceServiceTest extends TestCase
{public function testOccupiedArtificerAcceptsWithoutReceivingDownstreamAuthority():void{$root=sys_get_temp_dir().'/imperium-subordinate-acceptance-'.bin2hex(random_bytes(6));$ref=['resolution_id'=>'hagiography-subordinate-resolution-'.str_repeat('a',20),'office'=>'hagiography','subordinate_staff_class'=>'Chronicler'];$act=['act_id'=>'subordinate-construction-authorization-'.str_repeat('b',20),'resolutions'=>[$ref],'disposition'=>'AUTHORIZED_FOR_EXACT_RESOLUTIONS','construction_authority'=>true];$act['record_digest']=hash('sha256',CanonicalJson::encode($act));$deliveryId='subordinate-construction-delivery-'.str_repeat('c',20);$delivery=['schema'=>'imperium.foundry-subordinate-construction-authorization-delivery/v1','delivery_id'=>$deliveryId,'office'=>'foundry','target'=>'foundry.artificer','instance_id'=>'imperium-test','authorization_act_id'=>$act['act_id'],'authorization_act_digest'=>$act['record_digest'],'authorized_resolutions'=>[$ref],'status'=>'DELIVERED_PENDING_FOUNDRY_ACCEPTANCE','recipient_acceptance'=>null,'construction_authority'=>true,'construction_authority_exercisable'=>false,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false,'authorization_act'=>$act];$delivery['record_digest']=hash('sha256',CanonicalJson::encode($delivery));$dir=$root.'/var/imperium/offices/foundry/inbox/subordinate-construction-authorizations';mkdir($dir,0770,true);file_put_contents($dir.'/'.$deliveryId.'.json',json_encode($delivery,JSON_THROW_ON_ERROR));$bindingId='foundry-artificer-binding-'.str_repeat('d',20);$binding=['schema'=>'imperium.foundry-artificer-occupancy/v1','binding_id'=>$bindingId,'instance_id'=>'imperium-test','office'=>'foundry','seat'=>'foundry.artificer','manifestation_id'=>'artificer-manifestation','occupancy_generation'=>1,'status'=>'ACTIVE','binding_atomic'=>true,'execution_authority'=>false];$binding['record_digest']=hash('sha256',CanonicalJson::encode($binding));$dir=$root.'/var/imperium/offices/foundry/occupancy';mkdir($dir,0770,true);file_put_contents($dir.'/'.$bindingId.'.json',json_encode($binding,JSON_THROW_ON_ERROR));try{$service=new SubordinateConstructionAuthorizationAcceptanceService($root);$a=$service->accept($deliveryId,$bindingId);self::assertSame($a,$service->accept($deliveryId,$bindingId));self::assertSame('ACCEPTED_FOR_EXACT_SUBORDINATE_CONSTRUCTION',$a['disposition']);self::assertTrue($a['recipient_acceptance']);self::assertTrue($a['construction_authority']);self::assertTrue($a['construction_authority_exercisable']);self::assertSame([$ref],$a['authorized_resolutions']);self::assertFalse($a['persona_selection_authority']);self::assertFalse($a['profile_approval_authority']);self::assertFalse($a['spawning_authority']);self::assertFalse($a['seat_binding_authority']);self::assertFalse($a['execution_authority']);}finally{$this->removeTree($root);}}private function removeTree(string $path):void{if(!is_dir($path))return;foreach(array_diff(scandir($path)?:[],['.','..'])as$entry){$child=$path.'/'.$entry;is_dir($child)?$this->removeTree($child):unlink($child);}rmdir($path);}}
